W=$(cat /tmp/rx_workdir); cat > $W/b.sh <<'SH'
#!/bin/bash
# $1 = workdir ; rest = extra sd args. reads printf-format specs on stdin
W="$1"; shift
i=0
while IFS= read -r spec; do
  case "$spec" in ''|\#*) continue;; esac
  pat=$(printf -- "$spec")
  i=$((i+1))
  printf 'x' | /workspace/executable "$@" -- "$pat" 'R' >"$W/raw/.o" 2>"$W/raw/.e"
  code=$?
  printf '==== [%d] SPEC: %s\n-- exit: %d\n' "$i" "$spec" "$code"
  if [ -s "$W/raw/.e" ]; then
    echo "-- stderr:"; cat -A "$W/raw/.e"
  else
    echo "-- OK stdout: [$(cat "$W/raw/.o")]"
  fi
done
SH
chmod +x $W/b.sh
cat > $W/p_rep.txt <<'EOF'
*
